/// <summary>
/// Form datasource extension of CustVendNettingRuleForm and table <c>CustVendNettingRule</c>
/// </summary>
[ExtensionOf(formDataSourceStr(CustVendNettingRuleForm, CustVendNettingRule))]
final class METCustVendNettingRuleFormDS_Extension
{
}

Method.Source:
/// <summary>
/// Enable/Disable the Metcash sequence control based on the parameter setup.
/// </summary>
/// <returns></returns>
public int active()
{
    int ret = next active();

    if (VendParameters::find().METUseNettingSequence == NoYes::Yes)
    {
        this.formRun().design().controlName(formControlStr(CustVendNettingRuleForm, CustVendNettingRule_METSequence)).enabled(true);
    }
    else
    {
        this.formRun().design().controlName(formControlStr(CustVendNettingRuleForm, CustVendNettingRule_METSequence)).enabled(false);
    }

    return ret;
}
